#include "StdAfx.h"#include "ReadParamsFromEMF.h"#include "SignalTags.h"#include <macros/AutoCloser.h>#include <macros/StrHelps.h>#ifdef _DEBUG#define new DEBUG_NEW#undef THIS_FILEstatic char THIS_FILE[] = __FILE__;#endifusing namespace std;BOOL KReadParamsFromEMF::ReadSignalTags1_1000(LPCTSTR lpszPathName, LPCSTR lpszCsvComment){  m_readLine.clear();  m_fnLineParser = &KReadParamsFromEMF::SingleTextLineSignalTags;  if( RecursiveRead( lpszPathName ) > 0 )    AppendCommentTo<tNamedSignalTags, tNamedSignalTags::iterator>( lpszCsvComment, m_SignalTags );  else    ReadSignalTagsFromCsv( lpszCsvComment );  return TRUE;}BOOL KReadParamsFromEMF::ReadSignalTags1_4000(LPCTSTR lpszPathName, LPCSTR lpszCsvComment){  m_readLine.clear();  m_fnLineParser = &KReadParamsFromEMF::SingleTextLineSignalTags;  if( RecursiveRead( lpszPathName ) > 0 )    AppendCommentTo<tNamedSignalTags, tNamedSignalTags::iterator>( lpszCsvComment, m_SignalTags );  else    ReadSignalTagsFromCsv( lpszCsvComment );  return TRUE;}void KReadParamsFromEMF::ReadSignalTagsFromCsv( LPCSTR lpszCsvComment ){  FILE *pFileI = NULL;  errno_t res = fopen_s( &pFileI, lpszCsvComment, "rt" );  if( res )    return;  KAutoCloser<FILE*> fI( pFileI, fclose );  char tStr[1024] = {0};  int nLine = 0;  int nCol = 0;  while( fgets( tStr, _countof(tStr)-1, pFileI ) )  {    char szCol[24][64] = {};    ++nLine;    const int C = SplitString( tStr, szCol, ',', false );    ASSD( C < _countof(szCol) );    if( 1==nLine )      continue;    if( 0==szCol[5][0] )      continue;    ASSD( !strcmp(szCol[5], "Signal Tag") );    ISignalTagPtr I;    if( !strcmp(szCol[11], "Digital") )    {      KDigitalSignalTag *p = new KDigitalSignalTag;      I = p;      tNamedSignalTags::_Pairib res = m_SignalTags.insert( tNamedSignalTags::value_type( szCol[3], I ) );      if( !res.second )        continue;      I->SetDecPics( atoi(szCol[10]) );      p->SetOnLabel( szCol[12] );      p->SetOffLabel( szCol[13] );    }    else if( !strcmp(szCol[11], "Analog") )    {      KAnalogSignalTag *p = new KAnalogSignalTag;      I = p;      tNamedSignalTags::_Pairib res = m_SignalTags.insert( tNamedSignalTags::value_type( szCol[3], I ) );      if( !res.second )        continue;    }    else    {      ASSD(0);      continue;    }    I->SetDescription( szCol[4] );    I->SetNumber( atoi(szCol[6]) );    I->SetDataType( szCol[7] );    I->SetAccess( szCol[8] );    I->SetUnits( szCol[9] );    I->SetInitialSourceValue( szCol[14] );  }}static LPCSTR s_SkipText[]={  "Hex Addr",  "Dec Addr",  "Tag Name",  "Type",  //"#",  "Data Type",  "Access",  "EU",  "Dec Plcs",  "Tag Type",  "'On' Label",  "'Off' Label"};void KReadParamsFromEMF::SingleTextLineSignalTags(LPCSTR lpszText, RECTL *rc){  if( -1 != m_idSkipText )  {    m_idSkipText = -1;    return;  }  for( int i=0; i<_countof(s_SkipText); i++ )  {    if( lpszText==strstr( lpszText, s_SkipText[i]) )    {      m_idSkipText = i;      return;    }  }  string szText( lpszText );  size_t posHex = szText.find( "0x" );  if( 0==posHex )  {    if( !m_readLine.empty() )    {      //разбор      if( m_readLine.size()>7 )      {        //if( !m_readLine.at(5).compare("float 32") )        if( !m_readLine.at(8).compare("Analog") || !m_readLine.at(9).compare("Analog") )        {          ISignalTagPtr p = new KAnalogSignalTag(m_readLine);          m_SignalTags.insert( tNamedSignalTags::value_type( m_readLine.at(2), p ) );        }        //else if( !m_readLine.at(5).compare("unsigned 16") )        else if( !m_readLine.at(8).compare("Digital") ||  !m_readLine.at(9).compare("Digital") )        {          ISignalTagPtr p = new KDigitalSignalTag(m_readLine);          m_SignalTags.insert( tNamedSignalTags::value_type( m_readLine.at(2), p ) );        }        else        {          ASSD( 0 );        }      }    }    m_readLine.clear();  }  m_readLine.push_back( szText );}KReadParamsFromEMF::SReplaces KReadParamsFromEMF::replaces[]={  {'_', '-'},  {'_', '/'}};